CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'admin');
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS services(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,price INTEGER,duration INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT 'individual',items TEXT NOT NULL DEFAULT '[]',image TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,position INTEGER NOT NULL DEFAULT 0,configured INTEGER NOT NULL DEFAULT 0,featured INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS barbers(id TEXT PRIMARY KEY,name TEXT NOT NULL,services TEXT NOT NULL DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1,photo TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS working_hours(id TEXT PRIMARY KEY,barber_id TEXT NOT NULL REFERENCES barbers(id),day INTEGER NOT NULL,"start" TEXT NOT NULL,"end" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS time_blocks(id TEXT PRIMARY KEY,barber_id TEXT NOT NULL REFERENCES barbers(id),"start" TIMESTAMPTZ NOT NULL,"end" TIMESTAMPTZ NOT NULL,reason TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,reference TEXT UNIQUE NOT NULL,token_hash TEXT UNIQUE NOT NULL,customer TEXT NOT NULL,phone TEXT NOT NULL,barber_id TEXT NOT NULL REFERENCES barbers(id),services TEXT NOT NULL,"start" TIMESTAMPTZ NOT NULL,"end" TIMESTAMPTZ NOT NULL,total INTEGER,status TEXT NOT NULL,source TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS appointments_overlap ON appointments(barber_id,"start","end",status);
CREATE INDEX IF NOT EXISTS blocks_overlap ON time_blocks(barber_id,"start","end");
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gallery_images(id TEXT PRIMARY KEY,url TEXT NOT NULL,alt TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS content_draft(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_limits(key TEXT PRIMARY KEY,window_until BIGINT NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media_assets(id TEXT PRIMARY KEY,url TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);

CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='grecco_no_overlapping_appointments' AND conrelid='appointments'::regclass) THEN
  ALTER TABLE appointments ADD CONSTRAINT grecco_no_overlapping_appointments
  EXCLUDE USING gist (barber_id WITH =, tstzrange("start","end",'[)') WITH &&)
  WHERE (status IN ('confirmed','completed'));
 END IF;
END $$;
